import{_ as a,c as t,o as r,b0 as i}from"./chunks/framework.Dmsv_Tiv.js";const o="data:image/png;base64,",l="/media-docs/assets/image-20251107111710415.DX1GP351.png",n="/media-docs/assets/image-20251110163610968.BNFQRDK0.png",m=JSON.parse('{"title":"LV005-CSI简介","description":null,"frontmatter":{"title":"LV005-CSI简介","date":"2025-11-07T10:42:46.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/mipi/csi/126b140b95f610fc502a255e","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-07T10:42:46.271Z","fulluuid":"c502a255e1b641819e7efafce65cc20a","useduuid":"c502a255e"}},"headers":[],"relativePath":"sdoc/mipi/csi/126b140b95f610fc502a255e.md","filePath":"sdoc/15-MIPI/10-CSI/LV005-CSI简介.md","lastUpdated":1767537778000}'),c={name:"sdoc/mipi/csi/126b140b95f610fc502a255e.md"};function d(s,e,p,I,f,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="lv005-csi简介" tabindex="-1">LV005-CSI简介 <a class="header-anchor" href="#lv005-csi简介" aria-label="Permalink to &quot;LV005-CSI简介&quot;">​</a></h1><h2 id="一、csi-是什么" tabindex="-1">一、CSI 是什么 <a class="header-anchor" href="#一、csi-是什么" aria-label="Permalink to &quot;一、CSI 是什么&quot;">​</a></h2><h3 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p>直接先来官网看简介：<a href="https://www.mipi.org/specifications/csi-2" target="_blank" rel="noreferrer">Camera Serial Interface 2 (MIPI CSI-2) | MIPI</a></p><p><img src="'+o+'" alt="image-20251107104717561"></p><blockquote><p>A widely adopted, high-speed protocol for transmission of still and video images from image sensors to application processors</p><p>一种被广泛采用的高速协议，用于将静止图像和视频图像从图像传感器传输到应用处理器。</p></blockquote><p>CSI (Camera Serial Interface) 是 MIPI 定义的规范，用于连接摄像头和 CPU，传输摄像头的视频信号，最新的规范是 2012 发布的 CSI-3，使用的物理层为 M-PHY，应用层协议栈还需要连接 Uni-Pro 层。CSI-2 规范在 2005 发布、使用 D-PHY 作为物理层，它定义了发送器和接收器之间的标准数据传输和控制接口。</p><h3 id="_2-文档说明" tabindex="-1">2. 文档说明 <a class="header-anchor" href="#_2-文档说明" aria-label="Permalink to &quot;2. 文档说明&quot;">​</a></h3><p>其实学习 CSI-2 最好的还是看文档，官网文档为：《MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2)》，但是官网下载好像还挺麻烦，不过万能互联网上肯定什么都有啦，搜一搜就可以下载到啦：</p><ul><li><a href="https://gitee.com/docs-site/media-reference-guide/raw/master/05-MIPI/Specification_for_Camera_Serial_Interface_v4.0.1.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2), Version 4.0.1</a></li><li><a href="https://picture.iczhiku.com/resource/eetop/wYkfSsAFZOeaJvXx.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2), Version 0.04</a></li></ul><p>我们后面还需要了解底层协议 D-PHY，这个协议的文档参考《Specification for D-PHY》</p><ul><li><a href="https://gitee.com/docs-site/media-reference-guide/raw/master/05-MIPI/Specification_for_DPHY_v3.0.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for D-PHY, Version 3.0</a></li></ul><h2 id="二、csi-2-分层架构" tabindex="-1">二、CSI-2 分层架构 <a class="header-anchor" href="#二、csi-2-分层架构" aria-label="Permalink to &quot;二、CSI-2 分层架构&quot;">​</a></h2><p>我们来到《MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2)》文档的 5 CSI-2 Layer Definitions ：</p><table><tbody><tr><th rowspan="11"><img src="'+l+'" alt="image-20251107111710415" style="zoom:100%;"></th><th> 英文名称 </th><th> 名称 </th><th> 解释 </th></tr><tr><td> Transmitter </td><td> 发送端 </td><td> 包括了 MIPI 数组部分，转接板等实现 MIPI 信源传输的部分 </td></tr><tr><td> Receiver </td><td> 接收端 </td><td> 包括了转接板和商用接收端模块，负责解析收到的 MIPI 信源 </td></tr><tr><td> Application </td><td> 应用层 </td><td> 处理原始图像数据的各种算法模块 </td></tr><tr><td> Packing Formats </td><td> 组包层 </td><td> 负责将数据按照一定的次序，切割成 8bite 数据 </td></tr><tr><td> Low Level Protocaol </td><td> 协议层 </td><td> 为新生成的数据加上爆头包尾，形成符合协议要求的数据流 </td></tr><tr><td> Lane Management </td><td> 通道管理层 </td><td> 将生成的数据流按照一定次序和要求，进行读写管理，输出数据流 </td></tr><tr><td> PHY Layer </td><td> PHY 层 </td><td> 生成 MIPI 最后的信号波形 </td></tr><tr><td> Pixel </td><td> 像素数据 </td><td> 经过图像模块处理过的数据流，或者原始的图像数据流 </td></tr><tr><td> Data </td><td> 传输数据 </td><td> 经过 MIPI 模块切割或者加上包头包尾数据 </td></tr><tr><td> Control </td><td> 控制信号 </td><td> 模块间的控制数据流 </td></tr></tbody></table> 工作顺序： <p>（1）将原始的图像数据在应用层做相应的图像处理，包括白平衡/噪声去除和色彩还原等；</p><p>（2）将处理的数据进入组包层做数据分割以及重组，然后将其传输给底层协议层；</p><p>（3）底层协议层会根据数据类型产生包头，根据数据内容产生构成包围的校验序列，再将包头、数据本身和包尾组成起来发送给通道管理层；</p><p>（4）通道管理层模块按照通道的选通情况，合理分配数据到每个通道，之后数据经过数模转换进入到物理层传输；</p><p>（5）接收端在收到物理层数据后，再按照之前的逆序解包出原始的图像数据。</p><h3 id="_1-phy-layer" tabindex="-1">1. PHY Layer <a class="header-anchor" href="#_1-phy-layer" aria-label="Permalink to &quot;1. PHY Layer&quot;">​</a></h3><p>物理层指定了从串行的 bit 流中解析出 0 和 1 的相关传输介质（电导体）、输入输出电路以及时钟的规范。PHY 层规定了传输介质和电信号参数的特性，以及对 D-PHY 类型的物理层的时钟和数据 lane 之间的时序关系。</p><p>物理层规范也包含了发起 SOT（Start of Transmission）和 EOT（End of Transmission）等能够在传输、接收的 PHY 之间进行传输的带外信息所使用的机制。Bit 和 Byte 级别的同步机制也是 PHY 层的一部分。</p><h3 id="_2-protocol-layer" tabindex="-1">2. Protocol Layer <a class="header-anchor" href="#_2-protocol-layer" aria-label="Permalink to &quot;2. Protocol Layer&quot;">​</a></h3><p>协议层由几个子层组成，每个子层有不同的职责。CSI-2 协议能够在 host 侧处理器上用一个单独的接口处理多条数据流。协议层规定了多条数据流该如何标记和交织起来，以便每条数据流能够被正确地恢复出来。</p><ul><li>Pixel/Byte Packing/Unpacking Layer</li></ul><p>CSI-2 规范支持多种不同像素格式的图像应用，每像素 6 位到 24 位不等。在发送方中，本层在发送数据到 Low Level Protocol 层之前，将来自应用层的像素封包为字节数据。在接收方中，本层在发送数据到应用层之前，将来自 Low Level Protocol 层的字节数据解包为像素。8 位的像素数据在本层中传输时保持不变。</p><ul><li>Low Level Protocol</li></ul><p>LLP 主要包含了在 SoT 和 EoT 事件之间的 bit 和 byte 级别的同步方法，以及和下一层传递数据的方法。LLP 最小数据粒度是 1 个字节。LLP 也包含了一个字节内的 bit 值解析，即 Endian(大小端里的 Endian 的意思)的处理。</p><ul><li>Lane Management</li></ul><p>CSI-2 的 lane 是可扩展的。具体的数据 lane 的数量规范并没有给出限制，数据通道的数量可以是 1、2、3 或者 4 个，这取决于应用程序的带宽需求。发送侧分发（distributor 功能）来自出口方向数据流的字节到 1 条或多条 lane 上。接收侧则从一条或多条 lane 中收集字节并合并（merge 功能）到一个数据流上，复原出原始流的字节顺序。对于 C-PHY 物理层来说，本层专门分发字节对（16 bits）到数据 lane 或从数据 lane 中收集字节对。基于每 lane 的扰码功能是可选特性。</p><p>协议层的 <strong>数据组织形式是包</strong>（packet）。接口的发送侧会增加包头（header）和错误校验（error-checking）信息到即将被 LLP 发送的数据上。接收侧在 LLP 将包头剥掉，包头会被接收器中对应的逻辑所解析。错误校验信息可以用来做入口数据的完整性检查。</p><h3 id="_3-application-layer" tabindex="-1">3. Application Layer <a class="header-anchor" href="#_3-application-layer" aria-label="Permalink to &quot;3. Application Layer&quot;">​</a></h3><p>本层描述了更高层级的应用对于数据中的数据的处理，规范并不涵盖应用层。CSI-2 规范只给出了像素值和字节的映射关系。</p><h2 id="三、实现示例" tabindex="-1">三、实现示例 <a class="header-anchor" href="#三、实现示例" aria-label="Permalink to &quot;三、实现示例&quot;">​</a></h2><p>我们看一下 <a href="https://gitee.com/docs-site/media-reference-guide/raw/master/05-MIPI/Specification_for_Camera_Serial_Interface_v4.0.1.pdf" target="_blank" rel="noreferrer">MIPI Alliance Specification for Camera Serial Interface 2 (CSI-2), Version 4.0.1</a> 的 4 Overview of CSI-2 这一节：</p><p><img src="'+n+'" alt="image-20251110163610968"></p><p>上图表明使用 DPHY 作为物理层时，Camera 与 SOC 之间的硬件关系。SOC 的 CCI 组件通过 I2C 完成对 Camera 的配置，使其输出 mipi 信号，其中一对 Clock+/-则由 Clock Lane 标示，一对 DataN+/-则由 Data Lane 标示。</p><blockquote><p>参考文档：</p><p><a href="https://blog.csdn.net/vivo01/article/details/126241781" target="_blank" rel="noreferrer">MIPI CSI-2 笔记（1） -- CSI-2 概览和 CSI-2 的分层架构_csi2-CSDN 博客</a></p><p><a href="https://zhuanlan.zhihu.com/p/599531271" target="_blank" rel="noreferrer">(3 封私信) Camera | 2.MIPI、CSI 基础 - 知乎</a></p><p><a href="https://ldd.100ask.net/zh/13_V4L2/05_1.html" target="_blank" rel="noreferrer">05_MIPI摄像头驱动程序分析 — Linux设备驱动开发教程中心</a></p></blockquote>',40)])])}const C=a(c,[["render",d]]);export{m as __pageData,C as default};
